// Offline test of the records panel's rules (src/records_rules.h) and its text
// (src/records_text.h, generated by tools/gen_records.py):
//
//   x86_64-w64-mingw32-g++ -std=c++20 -O2 -static tests/test_records.cpp -o tests/build/test_records.exe
//   wine tests/build/test_records.exe
//
// The rules are what switching a record on or off writes, checked against the
// game's own check (RecordManager.checkClearedRecord) as records_rules.h
// restates it: a record switched on must pass it, one switched off must fail it.
// Then the Shop's points as RecordManager.addTotalShopPoint leaves them, and the
// harder difficulties' open state as the two mode records move it.
#include <cstdio>
#include <cstring>

#include "../src/records_rules.h"
#include "../src/records_text.h"

namespace {

using namespace re3cc::records;

int g_fail = 0;

void check(bool ok, const char* what) {
  std::printf("%s  %s\n", ok ? "ok  " : "FAIL", what);
  if (!ok) ++g_fail;
}

}  // namespace

int main() {
  char what[256];

  // --- the progress numbers ---------------------------------------------------------------------------------------
  const rules::ProgressTypes pt;  // this build: NONE 0, COUNT_UP 1, COUNT_DOWN 2; the rest (3..7) exactly
  check(rules::kind_of(pt, 0) == rules::kAtLeast && rules::kind_of(pt, 1) == rules::kAtLeast &&
            rules::kind_of(pt, 2) == rules::kWithin && rules::kind_of(pt, 3) == rules::kExactly &&
            rules::kind_of(pt, 7) == rules::kExactly,
        "ProgressType kinds: NONE/COUNT_UP at least, COUNT_DOWN within, CLEARTIME..ADA_GUN exactly");
  struct Case {
    rules::Kind kind;
    int progress, goal;
  };
  const Case cases[] = {{rules::kAtLeast, 0, 1},   {rules::kAtLeast, 1, 1},    {rules::kAtLeast, 3, 20},
                        {rules::kAtLeast, 20, 20}, {rules::kAtLeast, 250, 20}, {rules::kAtLeast, 2, 2},
                        {rules::kWithin, 0, 5},    {rules::kWithin, 4, 5},     {rules::kWithin, 5, 5},
                        {rules::kWithin, 9, 5},    {rules::kExactly, 0, 1},    {rules::kExactly, 1, 1},
                        {rules::kExactly, 0, 3},   {rules::kExactly, 3, 3},    {rules::kAtLeast, -1, 5}};
  int bad_on = 0, bad_off = 0, lost = 0;
  for (const Case& c : cases) {
    const int on = rules::on_progress(c.kind, c.progress, c.goal);
    const int off = rules::off_progress(c.kind, c.progress, c.goal);
    if (!rules::meets(c.kind, on, c.goal)) ++bad_on;
    if (rules::meets(c.kind, off, c.goal)) ++bad_off;
    // What earned it already is kept switching on; a count kept as close as it can be switching off.
    if (rules::meets(c.kind, c.progress, c.goal) && on != c.progress) ++lost;
    if (!rules::meets(c.kind, c.progress, c.goal) && off != c.progress) ++lost;
  }
  std::snprintf(what, sizeof(what), "on earns, off un-earns, by the game's check: %d/%d wrong, %d changed needlessly",
                bad_on, bad_off, lost);
  check(!bad_on && !bad_off && !lost, what);
  check(rules::on_progress(rules::kAtLeast, 3, 20) == 20 && rules::off_progress(rules::kAtLeast, 250, 20) == 19,
        "a count (zombies' hats): on puts it at the goal, off just short of it (one more earns it)");
  check(rules::on_progress(rules::kWithin, 4, 5) == 4 && rules::on_progress(rules::kWithin, 0, 5) == 5 &&
            rules::off_progress(rules::kWithin, 4, 5) == 0,
        "the fuses within so many minutes: a better time is kept, none becomes the goal; off is 0 (never done)");
  check(rules::off_progress(rules::kExactly, 1, 1) == 0 && rules::on_progress(rules::kExactly, 0, 1) == 1,
        "an end-of-game record: exactly its goal on, 0 off");

  // Rewards shared between records: one is taken back only when no other cleared record gives it.
  {
    bool cleared[3] = {true, true, false};
    const int rewards[3 * 4] = {7, 8, -1, -1, /*second*/ 9, 10, 7, 8, /*other*/ 55, -1, -1, -1};
    check(rules::granted_elsewhere(7, 0, cleared, rewards, 3, 4) && !rules::granted_elsewhere(9, 1, cleared, rewards, 3, 4),
          "a reward another cleared record gives stays; one no other gives goes");
    cleared[1] = false;
    check(!rules::granted_elsewhere(7, 0, cleared, rewards, 3, 4), "a reward only an uncleared record gives goes");
  }

  // The Charlie dolls (and the locks): the last ones counted come back first, down to what the record allows.
  {
    bool broken[20];
    for (bool& b : broken) b = true;
    check(rules::unmark_to(broken, 20, 19) == 1 && !broken[19] && broken[18],
          "all 20 dolls broken, 19 kept (\"Goodbye, Charlie!\" or \"Hello, Charlie!\" off): the last one back");
    check(rules::unmark_to(broken, 20, 0) == 19 && !broken[0], "down to 0: every doll back");
    check(rules::unmark_to(broken, 20, 0) == 0, "already at 0: nothing");
    bool some[5] = {false, true, false, true, true};
    check(rules::unmark_to(some, 5, 1) == 2 && some[1] && !some[3] && !some[4], "3 of 5 counted, 1 kept: the first stays");
  }

  // --- the Shop's points ---------------------------------------------------------------------------------------------
  check(rules::points_after(1000, 300, 999999) == 1300 && rules::points_after(1000, -300, 999999) == 700,
        "a record's points added on, taken back off");
  check(rules::points_after(200, -300, 999999) == 0, "never below 0: points already spent stay spent");
  check(rules::points_after(999000, 7000, 999999) == 999999, "never above the game's maximum (TOTAL_SHOP_POINT)");
  check(rules::points_after(0, 123456, 0) == 123456, "no maximum known: no cap");

  // --- Nightmare and Inferno (difficultyOpenState: NotOpened 0, OpenSuperHard 1, OpenUnlimited 2) ---------------------
  {
    const int kNightmare = 1, kInferno = 2;
    check(rules::open_state_on(0, kNightmare) == 1 && rules::open_state_on(0, kInferno) == 2,
          "a mode record on opens its mode");
    check(rules::open_state_on(2, kNightmare) == 2, "the Nightmare record on with Inferno open: never lowered");
    check(rules::open_state_off(1, kNightmare, 0) == 0, "the Nightmare record off, Inferno's not cleared: closed");
    check(rules::open_state_off(2, kNightmare, 2) == 2, "the Nightmare record off while Inferno's is cleared: Inferno stays open");
    check(rules::open_state_off(2, kInferno, 1) == 1, "the Inferno record off, Nightmare's still cleared: back to Nightmare");
    check(rules::open_state_off(2, kInferno, 0) == 0, "the Inferno record off, neither cleared: closed");
    check(rules::open_state_off(1, kInferno, 0) == 1, "the Inferno record off while only Nightmare was open: left alone");
  }

  // --- the generated text ------------------------------------------------------------------------------------------
  namespace rt_ = re3cc::records_text;
  int named = 0;
  for (const auto& r : rt_::kRecord) named += r.name != nullptr;
  std::snprintf(what, sizeof(what), "%d of %d records named", named, rt_::kRecords);
  check(rt_::kRecords == 91 && named == 91, what);
  check(rt_::kRecord[0].name && !std::strcmp(rt_::kRecord[0].name, "So Long, RC"), "RECORD_001 is So Long, RC");
  volatile int k18 = 17;  // RECORD_018 (a runtime index: GCC folds a constant one and warns)
  check(rt_::kRecord[k18].condition && std::strstr(rt_::kRecord[k18].condition, "{0}"), "RECORD_018's condition has {0}");
  volatile int k44 = 43, k45 = 44;
  check(rt_::kRecord[k44].name && !std::strcmp(rt_::kRecord[k44].name, "Minimalist") && rt_::kRecord[k45].name &&
            !std::strcmp(rt_::kRecord[k45].name, "I Might Need These Later!"),
        "RECORD_044 Minimalist, RECORD_045 I Might Need These Later! (the panel's two counters)");
  auto sorted_by_guid = [](const rt_::Text* t, size_t n) {
    for (size_t i = 1; i < n; ++i)
      if (!(t[i - 1].hi < t[i].hi || (t[i - 1].hi == t[i].hi && t[i - 1].lo < t[i].lo))) return false;
    return true;
  };
  constexpr size_t kN = sizeof(rt_::kRewardText) / sizeof(rt_::kRewardText[0]);
  std::snprintf(what, sizeof(what), "%zu reward texts, sorted by GUID for the lookup", kN);
  check(kN > 50 && sorted_by_guid(rt_::kRewardText, kN), what);
  bool ascii_ok = true;
  auto latin1_utf8 = [](const char* s) {
    for (const unsigned char* p = reinterpret_cast<const unsigned char*>(s); p && *p; ++p)
      if (*p >= 0x80 && *p != 0xC2 && *p != 0xC3 && (*p < 0x80 || *p > 0xBF)) return false;
    return true;
  };
  for (const auto& r : rt_::kRecord) ascii_ok = ascii_ok && latin1_utf8(r.name) && latin1_utf8(r.condition);
  for (size_t i = 0; i < kN; ++i) ascii_ok = ascii_ok && latin1_utf8(rt_::kRewardText[i].text);
  check(ascii_ok, "every text is Latin-1 in UTF-8 (the panel's font has those glyphs)");

  std::printf("%s: %d failure(s)\n", g_fail ? "FAILED" : "PASSED", g_fail);
  return g_fail ? 1 : 0;
}
